        if (username == null || username.trim().isEmpty()) {
            throw new IllegalArgumentException("Username must not be null or empty");
        }
        String safeUsername = HtmlUtils.htmlEscape(username.trim());
        return "<h1>Welcome, " + safeUsername + "!</h1>";
    }
